<?php
function product_tag_carousel_shortcode() {
    // Get all product tags
    $selected_tag_ids = get_option('gc_gift_item_slider_selected_tags', array());

    if (empty($selected_tag_ids) || is_wp_error($selected_tag_ids)) {
        return '<p>No tags selected for Gift Item Slider. Please configure in admin panel.</p>';
    }

    // Get tag objects in the order they were selected
    $tags = get_terms(array(
        'taxonomy' => 'product_tag',
        'include' => $selected_tag_ids,
        'hide_empty' => false,
        'orderby' => 'include'
    ));

    if (empty($tags) || is_wp_error($tags)) {
        return '<p>No valid tags found for Gift Item Slider.</p>';
    }
    // Sort tags to match the selected order
    $tag_map = array();
    foreach ($tags as $tag) {
        $tag_map[$tag->term_id] = $tag;
    }
    
    $ordered_tags = array();
    foreach ($selected_tag_ids as $tag_id) {
        if (isset($tag_map[$tag_id])) {
            $ordered_tags[] = $tag_map[$tag_id];
        }
    }
    
    $tags = $ordered_tags;
    $tag_count = count($tags);

    $button_url = get_field('persona_btn_link', 'option');
    $url = is_array($button_url) ? $button_url['url'] : $button_url;

    ob_start();
    ?>
    <div class="product-tag-carousel-section">
        <div class="tag-header">
            <h2 class="carousel-heading">Find the perfect gift card for <span class="font-ephesis">any personality</span></h2>
            <!-- <button class="btn-primary btn">SHOP ALL PERSONAS</button> -->
            <!-- <button class="btn-primary btn">SHOP ALL PERSONAS</button> -->
            <button
                id="shop-all-personas"
                class="btn-primary btn"
                data-url="<?php echo esc_url($url); ?>">
                SHOP ALL PERSONAS
            </button>
        </div>
        <div class="owl-carousel product-tag-carousel">
            <?php foreach ($tags as $tag):
                $image_id = get_term_meta($tag->term_id, 'tag-image-id', true);
                $image_url = $image_id ? wp_get_attachment_image_url($image_id, 'medium') : wc_placeholder_img_src(); 
                //$tag_link  = get_term_link($tag); 
                $tag_link  = home_url("persona/?tag=$tag->slug")

                ?>
                <div class="tag-item">
                    <a href="<?php echo esc_url($tag_link); ?>" class="tag-link" title="<?php echo esc_attr($tag->name); ?>">
                        <div class="tag-card">
                            <div class="tag-image">
                                <img src="<?php echo esc_url($image_url); ?>" alt="<?php echo esc_attr($tag->name); ?>">
                            </div>
                            <h4 class="tag-name"><?php echo esc_html($tag->name); ?></h4>
                        </div>
                    </a>
                </div>
            <?php endforeach; ?>
        </div>
    </div>

    <?php 
        if($tag_count <= 6){
    ?>
    <style type="text/css">
        .product-tag-carousel-section .owl-carousel.product-tag-carousel.owl-loaded.owl-drag .owl-nav.disabled {
            display: none !important;
        }
    </style>
<?php } ?>

